using System;
using System.Collections;
using System.IO;
using System.Text;
using UnityEngine;
public class OneDayCampaignProbe:MonoBehaviour {
 DriveSession s;bool ok=true;readonly StringBuilder report=new StringBuilder();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-oneDayTest")>=0||Array.IndexOf(Environment.GetCommandLineArgs(),"-oneDayReloadTest")>=0)new GameObject("One day campaign probe").AddComponent<OneDayCampaignProbe>();}
 void Check(bool v,string label){ok&=v;report.AppendLine((v?"PASS ":"FAIL ")+label);Directory.CreateDirectory("artifacts");File.WriteAllText("artifacts/one-day-runtime.txt","success="+ok+"\n"+report);}
 void At(int i){var stop=s.jobs.stops[i];s.taxi.body.position=stop.Kerb+Vector3.up*.65f;s.taxi.body.rotation=Quaternion.LookRotation(stop.Direction);s.taxi.transform.SetPositionAndRotation(s.taxi.body.position,s.taxi.body.rotation);Physics.SyncTransforms();}
 IEnumerator Capture(string name){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-captureOneDay")<0)yield break;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/day20-"+name+".png"));yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Start(){yield return new WaitForSecondsRealtime(2);s=FindObjectOfType<DriveSession>();var b=s.business;if(Array.IndexOf(Environment.GetCommandLineArgs(),"-oneDayReloadTest")>=0){Check(b.ledger.OneDay&&b.ShowingSummary&&b.completedDays.Count==2&&b.ledger.Driver.meals==1&&b.ledger.Driver.sleeps==1,"fresh process reloads two completed days and condition");Check(b.ComparisonVersion.EndsWith("off"),"saved traffic setting restored despite current ON");yield return Capture("reloaded-result");File.WriteAllText("artifacts/one-day-reload.txt",report.ToString());Application.Quit(ok?0:1);yield break;}Check(b.ledger.OneDay&&b.ledger.SecondsLeft>1195,"default one day 1200-second budget");if(!ok){Application.Quit(1);yield break;}
  b.preparing=true;Time.timeScale=0;yield return Capture("preparation");
  s.taxi.enabled=false;s.taxi.body.isKinematic=true;s.taxi.body.interpolation=RigidbodyInterpolation.None;s.taxi.body.detectCollisions=false;b.Depart();b.enabledCampaign=true;
  s.jobs.ClearForDay();At(7);Check(s.jobs.Interact(),"roadside boarding without scenario");string trip=s.law.tripId;float remaining=s.jobs.trip.Remaining;b.ledger.Driver.fatigue=100;yield return null;Check(s.jobs.trip.State==TripState.OnTrip&&s.law.tripId==trip,"fatigue does not remove passenger");Check(!b.RequestEndDay(),"no closing while occupied");b.ledger.Advance(1200,0);yield return null;Check(!b.ShowingSummary&&s.jobs.trip.State==TripState.OnTrip&&s.jobs.trip.Remaining<=remaining,"time limit retains trip and deadline");At(s.jobs.current.drop);Check(s.jobs.Interact(),"last passenger can alight without scenario");yield return null;yield return null;Check(b.ShowingSummary&&b.ledger.State==BusinessState.Completed,"last alighting settles day");Check(b.SaveCheckpoint(),"save completed result");
  Check(b.RequestRestart(),"result restart confirm");Check(!b.ConfirmRestart(false)&&b.ShowingSummary,"restart cancel preserves result");Check(b.RequestRestart(),"restart retry");var old=b.ledger;string oldBytes=File.ReadAllText(b.SavePath);Directory.CreateDirectory(b.SavePath+".tmp");try{Check(!b.ConfirmRestart(true)&&b.ledger==old&&File.ReadAllText(b.SavePath)==oldBytes,"save failure leaves old state");}finally{Directory.Delete(b.SavePath+".tmp");}Check(b.ConfirmRestart(true),"restart after failed save");yield return null;b.Depart();
  Check(b.ledger.Account.Fuel==60&&b.ledger.Driver.satiety==80&&b.ledger.Driver.fatigue==10&&s.law.ledger.TotalScore==100,"new day initial values");Check(b.completedDays.Count==1&&File.ReadAllText(b.SavePath).Contains("completedDays"),"completed history retained once");Check(b.SavePath.EndsWith("one-day-test.json"),"new mode has separate save path");
  s.jobs.ClearForDay();At(7);Check(s.jobs.Accept(0),"accept pickup before fatigue limit");b.ledger.Driver.fatigue=100;yield return null;Check(s.jobs.trip.State==TripState.Idle&&!s.jobs.Accept(0)&&!s.jobs.Interact(),"fatigue cancels pickup and blocks new ride");
  At(s.services.indices[2]);s.services.Toggle();yield return Capture("services");Check(s.services.open&&s.services.RequestAction(3),"sleep available at parking despite fatigue");yield return Capture("sleep-confirm");double t=b.ledger.Elapsed;Check(s.services.ConfirmAction(true)&&Math.Abs(b.ledger.Elapsed-t-100)<.1&&b.ledger.Driver.fatigue<61,"sleep time and recovery");
  At(s.services.indices[1]);s.services.Toggle();Check(s.services.RequestAction(1),"meal confirmation");int cash=b.ledger.Account.Cash;float fuel=b.ledger.Account.Fuel;t=b.ledger.Elapsed;Check(!s.services.ConfirmAction(false)&&b.ledger.Account.Cash==cash&&b.ledger.Elapsed==t,"meal cancel no effects");Check(s.services.RequestAction(1)&&s.services.ConfirmAction(true)&&b.ledger.Account.Cash==cash-3000&&Math.Abs(b.ledger.Elapsed-t-50)<.1&&Math.Abs(b.ledger.Account.Fuel-fuel)<.001,"meal 50s engine off");
  b.ledger.Driver.satiety=20;b.ledger.Driver.fatigue=80;s.services.Toggle();t=b.ledger.Elapsed;yield return new WaitForSecondsRealtime(.4f);Check(b.ledger.Elapsed==t&&b.ledger.Driver.satiety==20&&b.ledger.Driver.fatigue==80,"service menu freezes time and condition");s.services.Toggle();
  At(s.services.indices[2]);Check(b.RequestEndDay(),"early parking close while tired allowed");yield return null;yield return null;Check(b.ShowingSummary&&b.ledger.Last.driver.meals==1&&b.ledger.Last.driver.sleeps==1,"summary service counts");var data=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(b.SavePath));var restored=EconomyLedger.RestoreCampaign(data.days,data.account);Check(restored.Driver.meals==1&&restored.Driver.sleeps==1&&restored.TotalNet==b.ledger.TotalNet,"condition and account same restore boundary");
  Check(b.completedDays.Count==2&&b.SaveCheckpoint()&&b.completedDays.Count==2,"settlement retry no duplicate result");yield return Capture("result");Application.Quit(ok?0:1);
 }
}
